sys_script_include.script:
var ITAccessUtils = Class.create();
ITAccessUtils.prototype = {
    initialize: function() {},

    // Return manager sys_id for a user
    getManager: function(userSysId) {
		gs.info('script include 1 ', userGr);
        if (!userSysId) return '';
        var userGr = new GlideRecord('sys_user');
		gs.info('script include ', userGr.manager);
        if (userGr.get(userSysId) && userGr.manager) {
            return userGr.manager.toString();
        }
        return '';
    },

    // Check active duplicate requests for same user + access type (+ app when applicable).
    // Returns "true" if duplicate found, else "false".
    hasActiveDuplicate: function(userSysId, accessType, applicationName) {
        if (!userSysId || !accessType) return false;
        var gr = new GlideRecord('x_58872_needit_u_it_access_request');
        gr.addQuery('requested_by', userSysId);
        gr.addQuery('access_type', accessType);
        // Active statuses: New, In Progress (change to whatever statuses you consider active)
        gr.addQuery('status', 'IN', 'New,In Progress');
        if (accessType === 'Application' && applicationName) {
            gr.addQuery('application_name', applicationName);
        }
        gr.query();
        return gr.hasNext();
    },

    // Utility to generate next request number (optional: can use number maintenance table)
    generateRequestNumber: function() {
        // Simple approach: prefix + timestamp
        var ts = new GlideDateTime().getNumericValue().toString();
        return 'ITREQ-' + ts;
    },

    type: 'ITAccessUtils'
};
